```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureApp {
    public static void main(String[] args) {
        String userInput = "1"; // 사용자가 입력한 값 (SQL 인젝션 방지)
        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");

            // PreparedStatement를 사용하여 SQL 인젝션 방지
            String query = "SELECT * FROM users WHERE id = ?";
            PreparedStatement pstmt = conn.prepareStatement(query);
            pstmt.setString(1, userInput); // 사용자 입력을 안전하게 설정

            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                System.out.println("User: " + rs.getString("username"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

위의 첫 번째 코드 스니펫에서는 SQL 인젝션 취약점이 존재합니다. 사용자가 입력한 값이 SQL 쿼리에 직접 삽입되기 때문에 공격자가 악의적인 입력을 통해 데이터베이스를 조작할 수 있습니다. 두 번째 코드 스니펫에서는 `PreparedStatement`를 사용하여 사용자 입력을 안전하게 처리함으로써 SQL 인젝션 취약점을 방지합니다.

